describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with zero upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: -1, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 500, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer bracket values", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 500.5, costCents: 100 }]),
      ).toThrow(RangeError);
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 500, costCents: 100.5 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 500, costCents: 100 }], -1),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 500, costCents: 100 }], 10.5),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const brackets = [
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 500 },
      { upToGrams: 5000, costCents: 1200 },
    ];

    it("returns 0 for empty cart", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([], 0)).toBe(0);
    });

    it("returns 0 when total weight is 0 (no weightGrams)", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([noWeightLine("a", 3)], 1000)).toBe(0);
    });

    it("selects the first bracket that covers the weight", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 400g ≤ 500 → 300
      expect(calc.computeShippingCents([line("a", 400)], 1000)).toBe(300);
    });

    it("uses exact boundary of a bracket", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 500g ≤ 500 → 300
      expect(calc.computeShippingCents([line("a", 500)], 1000)).toBe(300);
    });

    it("jumps to next bracket above boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 501g > 500, ≤ 1000 → 500
      expect(calc.computeShippingCents([line("a", 501)], 1000)).toBe(500);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      const calc = new WeightBasedShippingCalculator(brackets, 2000);
      // 6000g > 5000 → overflow 2000
      expect(calc.computeShippingCents([line("a", 6000)], 1000)).toBe(2000);
    });

    it("falls back to heaviest bracket cost when no overflow specified", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 6000g > 5000 → last bracket 1200
      expect(calc.computeShippingCents([line("a", 6000)], 1000)).toBe(1200);
    });

    it("sums weight from multiple lines with quantity", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 200g * 3 = 600g → second bracket (500 < 600 ≤ 1000) → 500
      expect(calc.computeShippingCents([line("a", 200, 3)], 1000)).toBe(500);
    });

    it("sorts brackets internally regardless of input order", () => {
      const calc = new WeightBasedShippingCalculator([
        { upToGrams: 5000, costCents: 1200 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 500 },
      ]);
      expect(calc.computeShippingCents([line("a", 400)], 1000)).toBe(300);
    });
  });
});

