import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const line = (
  id: string,
  weightGrams: number,
  quantity = 1,
): CartLine => ({
  product: { id, name: id, unitPriceCents: 100, weightGrams },
  quantity,
});

const noWeightLine = (id: string, quantity = 1): CartLine => ({
  product: { id, name: id, unitPriceCents: 100 },
  quantity,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for non-empty cart", () => {
    expect(calc.computeShippingCents([line("a", 500)], 1000)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(5.5)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 10.5)).toThrow(RangeError);
    });

    it("accepts zero flatCents", () => {
      expect(() => new FlatShippingCalculator(0)).not.toThrow();
    });

    it("accepts zero freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 0)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns flat fee for non-empty cart", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([line("a", 500)], 2000)).toBe(599);
    });

    it("returns 0 for empty cart", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([], 0)).toBe(0);
    });

    it("returns 0 when subtotal meets freeOver threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([line("a", 500)], 5000)).toBe(0);
    });

    it("returns 0 when subtotal exceeds freeOver threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([line("a", 500)], 6000)).toBe(0);
    });

    it("returns flat fee when subtotal below freeOver threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([line("a", 500)], 4999)).toBe(599);
    });

    it("without freeOver, always charges flat fee for non-empty cart", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([line("a", 500)], 100000)).toBe(599);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with zero upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: -1, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 500, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer bracket values", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 500.5, costCents: 100 }]),
      ).toThrow(RangeError);
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 500, costCents: 100.5 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 500, costCents: 100 }], -1),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 500, costCents: 100 }], 10.5),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const brackets = [
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 500 },
      { upToGrams: 5000, costCents: 1200 },
    ];

    it("returns 0 for empty cart", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([], 0)).toBe(0);
    });

    it("returns 0 when total weight is 0 (no weightGrams)", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([noWeightLine("a", 3)], 1000)).toBe(0);
    });

    it("selects the first bracket that covers the weight", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 400g ≤ 500 → 300
      expect(calc.computeShippingCents([line("a", 400)], 1000)).toBe(300);
    });

    it("uses exact boundary of a bracket", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 500g ≤ 500 → 300
      expect(calc.computeShippingCents([line("a", 500)], 1000)).toBe(300);
    });

    it("jumps to next bracket above boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 501g > 500, ≤ 1000 → 500
      expect(calc.computeShippingCents([line("a", 501)], 1000)).toBe(500);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      const calc = new WeightBasedShippingCalculator(brackets, 2000);
      // 6000g > 5000 → overflow 2000
      expect(calc.computeShippingCents([line("a", 6000)], 1000)).toBe(2000);
    });

    it("falls back to heaviest bracket cost when no overflow specified", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 6000g > 5000 → last bracket 1200
      expect(calc.computeShippingCents([line("a", 6000)], 1000)).toBe(1200);
    });

    it("sums weight from multiple lines with quantity", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 200g * 3 = 600g → second bracket (500 < 600 ≤ 1000) → 500
      expect(calc.computeShippingCents([line("a", 200, 3)], 1000)).toBe(500);
    });

    it("sorts brackets internally regardless of input order", () => {
      const calc = new WeightBasedShippingCalculator([
        { upToGrams: 5000, costCents: 1200 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 500 },
      ]);
      expect(calc.computeShippingCents([line("a", 400)], 1000)).toBe(300);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import {
  InventoryError,
  refreshPrices,
  type PriceFetcher,
} from "../src/inventory.ts";
import type { CartLine, Product } from "../src/product.ts";

function mkLine(id: string, price: number, qty = 1): CartLine {
  return {
    product: { id, name: id, unitPriceCents: price },
    quantity: qty,
  };
}

describe("InventoryError", () => {
  it("exposes productId, requested, and available properties", () => {
    const err = new InventoryError("out of stock", "p1", 5, 2);
    expect(err).toBeInstanceOf(Error);
    expect(err.name).toBe("InventoryError");
    expect(err.message).toBe("out of stock");
    expect(err.productId).toBe("p1");
    expect(err.requested).toBe(5);
    expect(err.available).toBe(2);
  });

  it("available can be undefined", () => {
    const err = new InventoryError("gone", "p2", 3, undefined);
    expect(err.available).toBeUndefined();
  });
});

describe("refreshPrices", () => {
  it("updates unitPriceCents from fetcher for each line", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn()
        .mockResolvedValueOnce(500)
        .mockResolvedValueOnce(1200),
    };
    const lines = [mkLine("a", 100, 2), mkLine("b", 200, 1)];
    const result = await refreshPrices(lines, fetcher);

    expect(result).toHaveLength(2);
    expect(result[0]!.product.unitPriceCents).toBe(500);
    expect(result[0]!.quantity).toBe(2);
    expect(result[1]!.product.unitPriceCents).toBe(1200);
    expect(result[1]!.quantity).toBe(1);
  });

  it("preserves other product fields", async () => {
    const product: Product = {
      id: "a",
      name: "Widget",
      unitPriceCents: 100,
      weightGrams: 250,
      currency: "EUR",
    };
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(999),
    };
    const result = await refreshPrices([{ product, quantity: 1 }], fetcher);
    expect(result[0]!.product.name).toBe("Widget");
    expect(result[0]!.product.weightGrams).toBe(250);
    expect(result[0]!.product.currency).toBe("EUR");
    expect(result[0]!.product.unitPriceCents).toBe(999);
  });

  it("throws RangeError for negative price from fetcher", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(-1),
    };
    await expect(refreshPrices([mkLine("a", 100)], fetcher)).rejects.toThrow(
      RangeError,
    );
  });

  it("throws RangeError for non-integer price from fetcher", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(10.5),
    };
    await expect(refreshPrices([mkLine("a", 100)], fetcher)).rejects.toThrow(
      RangeError,
    );
  });

  it("propagates fetcher rejection", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("service down")),
    };
    await expect(refreshPrices([mkLine("a", 100)], fetcher)).rejects.toThrow(
      "service down",
    );
  });

  it("returns empty array for empty lines", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn(),
    };
    const result = await refreshPrices([], fetcher);
    expect(result).toEqual([]);
    expect(fetcher.fetchPriceCents).not.toHaveBeenCalled();
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import { InventoryError, type PriceFetcher, type InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import {
  PercentageDiscountPolicy,
  RegionalTaxCalculator,
  FlatShippingCalculator,
} from "../src/index.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2000, weightGrams: 500 };

describe("Cart – line management", () => {
  it("adds a product and reflects in itemCount", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    expect(cart.itemCount).toBe(2);
  });

  it("merges quantities when adding same product twice", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    cart.add(productA, 3);
    expect(cart.itemCount).toBe(5);
  });

  it("tracks distinct products separately", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    cart.add(productB, 2);
    expect(cart.itemCount).toBe(3);
  });

  it("rejects non-positive quantity on add", () => {
    const cart = new Cart();
    expect(() => cart.add(productA, 0)).toThrow(RangeError);
    expect(() => cart.add(productA, -1)).toThrow(RangeError);
    expect(() => cart.add(productA, 1.5)).toThrow(RangeError);
  });

  it("rejects negative unitPriceCents on add", () => {
    const cart = new Cart();
    const bad: Product = { id: "x", name: "X", unitPriceCents: -1 };
    expect(() => cart.add(bad, 1)).toThrow(RangeError);
  });

  it("remove returns true for existing product", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove returns false for unknown product", () => {
    const cart = new Cart();
    expect(cart.remove("unknown")).toBe(false);
  });

  it("updateQuantity changes the line quantity", () => {
    const cart = new Cart();
    cart.add(productA, 3);
    cart.updateQuantity("a", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("updateQuantity with 0 removes the product", () => {
    const cart = new Cart();
    cart.add(productA, 3);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
    expect(cart.remove("a")).toBe(false);
  });

  it("updateQuantity throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("unknown", 5)).toThrow("not in the cart");
  });

  it("updateQuantity rejects negative quantity", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("updateQuantity rejects non-integer quantity", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", 1.5)).toThrow(RangeError);
  });

  it("clear empties the cart", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    cart.add(productB, 3);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns a deep copy", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const snap = cart.snapshot();
    expect(snap).toHaveLength(1);
    expect(snap[0]!.product.id).toBe("a");
    expect(snap[0]!.quantity).toBe(2);

    // Mutating snapshot doesn't affect cart
    (snap[0] as { quantity: number }).quantity = 99;
    expect(cart.itemCount).toBe(2);
  });
});

describe("Cart – totals pipeline", () => {
  it("computes subtotal as sum of unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(productA, 2); // 1000 * 2 = 2000
    cart.add(productB, 1); // 2000 * 1 = 2000
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(4000);
  });

  it("empty cart has all-zero totals", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(0);
    expect(totals.discountCents).toBe(0);
    expect(totals.taxCents).toBe(0);
    expect(totals.shippingCents).toBe(0);
    expect(totals.totalCents).toBe(0);
  });

  it("applies discount, then taxes on discounted subtotal", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(175),
    };
    const cart = new Cart({
      discountPolicy: discount,
      taxCalculator: tax,
    });
    cart.add(productA, 2); // subtotal = 2000

    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(2000);
    expect(totals.discountCents).toBe(500);
    // Tax must be called with discounted subtotal (2000 - 500 = 1500)
    expect(tax.computeTaxCents).toHaveBeenCalledWith(1500, "US");
    expect(totals.taxCents).toBe(175);
    expect(totals.totalCents).toBe(1500 + 175); // discounted + tax + 0 shipping
  });

  it("clamps discount to [0, subtotal]", () => {
    const overDiscount: DiscountPolicy = {
      computeDiscountCents: () => 99999,
    };
    const cart = new Cart({ discountPolicy: overDiscount });
    cart.add(productA, 1); // subtotal 1000
    expect(cart.totals().discountCents).toBe(1000);
    expect(cart.totals().totalCents).toBe(0);
  });

  it("clamps negative discount to 0", () => {
    const negDiscount: DiscountPolicy = {
      computeDiscountCents: () => -500,
    };
    const cart = new Cart({ discountPolicy: negDiscount });
    cart.add(productA, 1);
    expect(cart.totals().discountCents).toBe(0);
  });

  it("clamps negative tax to 0", () => {
    const negativeTax: TaxCalculator = {
      computeTaxCents: () => -100,
    };
    const cart = new Cart({ taxCalculator: negativeTax });
    cart.add(productA, 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const negativeShipping: ShippingCalculator = {
      computeShippingCents: () => -100,
    };
    const cart = new Cart({ shippingCalculator: negativeShipping });
    cart.add(productA, 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("total = discountedSubtotal + tax + shipping", () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(10),
      taxCalculator: new RegionalTaxCalculator({ US: 0.08 }),
      shippingCalculator: new FlatShippingCalculator(500),
      region: "US",
    });
    cart.add(productA, 5); // subtotal = 5000
    const totals = cart.totals();
    // discount = floor(10% of 5000) = 500
    expect(totals.discountCents).toBe(500);
    // tax = floor(8% of 4500) = floor(360) = 360
    expect(totals.taxCents).toBe(360);
    expect(totals.shippingCents).toBe(500);
    // total = 4500 + 360 + 500 = 5360
    expect(totals.totalCents).toBe(5360);
  });

  it("shipping receives discounted subtotal", () => {
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(100),
    };
    const discount: DiscountPolicy = {
      computeDiscountCents: () => 300,
    };
    const cart = new Cart({
      discountPolicy: discount,
      shippingCalculator: shipping,
    });
    cart.add(productA, 1); // subtotal 1000, discount 300, discounted 700
    cart.totals();
    expect(shipping.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      700,
    );
  });

  it("defaults to US region", () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: tax });
    cart.add(productA, 1);
    cart.totals();
    expect(tax.computeTaxCents).toHaveBeenCalledWith(expect.any(Number), "US");
  });

  it("uses custom region", () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: tax, region: "FR" });
    cart.add(productA, 1);
    cart.totals();
    expect(tax.computeTaxCents).toHaveBeenCalledWith(expect.any(Number), "FR");
  });
});

describe("Cart – checkout()", () => {
  it("returns totals and lines for a simple checkout", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(1000);
    expect(result.lines).toHaveLength(1);
  });

  it("refreshes prices via priceFetcher before computing totals", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };
    const cart = new Cart();
    cart.add(productA, 2); // original 1000 each
    const result = await cart.checkout({ priceFetcher: fetcher });
    // After refresh: 1500 each × 2 = 3000
    expect(result.totals.subtotalCents).toBe(3000);
    expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("a");
  });

  it("throws InventoryError when inventory reports unavailable", async () => {
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: false, reason: "out of stock" }),
    };
    const cart = new Cart();
    cart.add(productA, 2);
    try {
      await cart.checkout({ inventoryChecker: checker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(2);
      expect(invErr.message).toBe("out of stock");
    }
  });

  it("throws InventoryError on partial-stock denial (availableQuantity < requested)", async () => {
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 1,
      }),
    };
    const cart = new Cart();
    cart.add(productA, 5);
    try {
      await cart.checkout({ inventoryChecker: checker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(5);
      expect(invErr.available).toBe(1);
    }
  });

  it("passes when inventory is available with sufficient quantity", async () => {
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 10,
      }),
    };
    const cart = new Cart();
    cart.add(productA, 3);
    const result = await cart.checkout({ inventoryChecker: checker });
    expect(result.totals.subtotalCents).toBe(3000);
  });

  it("passes when inventory is available without availableQuantity", async () => {
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const cart = new Cart();
    cart.add(productA, 1);
    const result = await cart.checkout({ inventoryChecker: checker });
    expect(result.totals.subtotalCents).toBe(1000);
  });

  it("uses asyncTaxProvider for tax computation", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const cart = new Cart({
      discountPolicy: { computeDiscountCents: () => 0 },
    });
    cart.add(productA, 1); // subtotal 1000
    const result = await cart.checkout({ asyncTaxProvider: provider });
