import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import { InventoryError, type PriceFetcher, type InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import {
  PercentageDiscountPolicy,
  RegionalTaxCalculator,
  FlatShippingCalculator,
} from "../src/index.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2000, weightGrams: 500 };

describe("Cart – line management", () => {
  it("adds a product and reflects in itemCount", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    expect(cart.itemCount).toBe(2);
  });

  it("merges quantities when adding same product twice", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    cart.add(productA, 3);
    expect(cart.itemCount).toBe(5);
  });

  it("tracks distinct products separately", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    cart.add(productB, 2);
    expect(cart.itemCount).toBe(3);
  });

  it("rejects non-positive quantity on add", () => {
    const cart = new Cart();
    expect(() => cart.add(productA, 0)).toThrow(RangeError);
    expect(() => cart.add(productA, -1)).toThrow(RangeError);
    expect(() => cart.add(productA, 1.5)).toThrow(RangeError);
  });

  it("rejects negative unitPriceCents on add", () => {
    const cart = new Cart();
    const bad: Product = { id: "x", name: "X", unitPriceCents: -1 };
    expect(() => cart.add(bad, 1)).toThrow(RangeError);
  });

  it("remove returns true for existing product", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove returns false for unknown product", () => {
    const cart = new Cart();
    expect(cart.remove("unknown")).toBe(false);
  });

  it("updateQuantity changes the line quantity", () => {
    const cart = new Cart();
    cart.add(productA, 3);
    cart.updateQuantity("a", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("updateQuantity with 0 removes the product", () => {
    const cart = new Cart();
    cart.add(productA, 3);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
    expect(cart.remove("a")).toBe(false);
  });

  it("updateQuantity throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("unknown", 5)).toThrow("not in the cart");
  });

  it("updateQuantity rejects negative quantity", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("updateQuantity rejects non-integer quantity", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", 1.5)).toThrow(RangeError);
  });

  it("clear empties the cart", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    cart.add(productB, 3);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns a deep copy", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const snap = cart.snapshot();
    expect(snap).toHaveLength(1);
    expect(snap[0]!.product.id).toBe("a");
    expect(snap[0]!.quantity).toBe(2);

    // Mutating snapshot doesn't affect cart
    (snap[0] as { quantity: number }).quantity = 99;
    expect(cart.itemCount).toBe(2);
  });
});

describe("Cart – totals pipeline", () => {
  it("computes subtotal as sum of unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(productA, 2); // 1000 * 2 = 2000
    cart.add(productB, 1); // 2000 * 1 = 2000
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(4000);
  });

  it("empty cart has all-zero totals", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(0);
    expect(totals.discountCents).toBe(0);
    expect(totals.taxCents).toBe(0);
    expect(totals.shippingCents).toBe(0);
    expect(totals.totalCents).toBe(0);
  });

  it("applies discount, then taxes on discounted subtotal", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(175),
    };
    const cart = new Cart({
      discountPolicy: discount,
      taxCalculator: tax,
    });
    cart.add(productA, 2); // subtotal = 2000

    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(2000);
    expect(totals.discountCents).toBe(500);
    // Tax must be called with discounted subtotal (2000 - 500 = 1500)
    expect(tax.computeTaxCents).toHaveBeenCalledWith(1500, "US");
    expect(totals.taxCents).toBe(175);
    expect(totals.totalCents).toBe(1500 + 175); // discounted + tax + 0 shipping
  });

  it("clamps discount to [0, subtotal]", () => {
    const overDiscount: DiscountPolicy = {
      computeDiscountCents: () => 99999,
    };
    const cart = new Cart({ discountPolicy: overDiscount });
    cart.add(productA, 1); // subtotal 1000
    expect(cart.totals().discountCents).toBe(1000);
    expect(cart.totals().totalCents).toBe(0);
  });

  it("clamps negative discount to 0", () => {
    const negDiscount: DiscountPolicy = {
      computeDiscountCents: () => -500,
    };
    const cart = new Cart({ discountPolicy: negDiscount });
    cart.add(productA, 1);
    expect(cart.totals().discountCents).toBe(0);
  });

  it("clamps negative tax to 0", () => {
    const negativeTax: TaxCalculator = {
      computeTaxCents: () => -100,
    };
    const cart = new Cart({ taxCalculator: negativeTax });
    cart.add(productA, 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const negativeShipping: ShippingCalculator = {
      computeShippingCents: () => -100,
    };
    const cart = new Cart({ shippingCalculator: negativeShipping });
    cart.add(productA, 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("total = discountedSubtotal + tax + shipping", () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(10),
      taxCalculator: new RegionalTaxCalculator({ US: 0.08 }),
      shippingCalculator: new FlatShippingCalculator(500),
      region: "US",
    });
    cart.add(productA, 5); // subtotal = 5000
    const totals = cart.totals();
    // discount = floor(10% of 5000) = 500
    expect(totals.discountCents).toBe(500);
    // tax = floor(8% of 4500) = floor(360) = 360
    expect(totals.taxCents).toBe(360);
    expect(totals.shippingCents).toBe(500);
    // total = 4500 + 360 + 500 = 5360
    expect(totals.totalCents).toBe(5360);
  });

  it("shipping receives discounted subtotal", () => {
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(100),
    };
    const discount: DiscountPolicy = {
      computeDiscountCents: () => 300,
    };
    const cart = new Cart({
      discountPolicy: discount,
      shippingCalculator: shipping,
    });
    cart.add(productA, 1); // subtotal 1000, discount 300, discounted 700
    cart.totals();
    expect(shipping.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      700,
    );
  });

  it("defaults to US region", () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: tax });
    cart.add(productA, 1);
    cart.totals();
    expect(tax.computeTaxCents).toHaveBeenCalledWith(expect.any(Number), "US");
  });

  it("uses custom region", () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: tax, region: "FR" });
    cart.add(productA, 1);
    cart.totals();
    expect(tax.computeTaxCents).toHaveBeenCalledWith(expect.any(Number), "FR");
  });
});

describe("Cart – checkout()", () => {
  it("returns totals and lines for a simple checkout", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(1000);
    expect(result.lines).toHaveLength(1);
  });

  it("refreshes prices via priceFetcher before computing totals", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };
    const cart = new Cart();
    cart.add(productA, 2); // original 1000 each
    const result = await cart.checkout({ priceFetcher: fetcher });
    // After refresh: 1500 each × 2 = 3000
    expect(result.totals.subtotalCents).toBe(3000);
    expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("a");
  });

  it("throws InventoryError when inventory reports unavailable", async () => {
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: false, reason: "out of stock" }),
    };
    const cart = new Cart();
    cart.add(productA, 2);
    try {
      await cart.checkout({ inventoryChecker: checker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(2);
      expect(invErr.message).toBe("out of stock");
    }
  });

  it("throws InventoryError on partial-stock denial (availableQuantity < requested)", async () => {
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 1,
      }),
    };
    const cart = new Cart();
    cart.add(productA, 5);
    try {
      await cart.checkout({ inventoryChecker: checker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(5);
      expect(invErr.available).toBe(1);
    }
  });

  it("passes when inventory is available with sufficient quantity", async () => {
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 10,
      }),
    };
    const cart = new Cart();
    cart.add(productA, 3);
    const result = await cart.checkout({ inventoryChecker: checker });
    expect(result.totals.subtotalCents).toBe(3000);
  });

  it("passes when inventory is available without availableQuantity", async () => {
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const cart = new Cart();
    cart.add(productA, 1);
    const result = await cart.checkout({ inventoryChecker: checker });
    expect(result.totals.subtotalCents).toBe(1000);
  });

  it("uses asyncTaxProvider for tax computation", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const cart = new Cart({
      discountPolicy: { computeDiscountCents: () => 0 },
    });
    cart.add(productA, 1); // subtotal 1000
    const result = await cart.checkout({ asyncTaxProvider: provider });
    // 10% of 1000 = 100
    expect(result.totals.taxCents).toBe(100);
    expect(provider.getRate).toHaveBeenCalledWith("US");
  });

  it("combines priceFetcher, inventoryChecker, and asyncTaxProvider", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(2000),
    };
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.05),
    };
    const discount: DiscountPolicy = {
      computeDiscountCents: () => 200,
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: () => 300,
    };
    const cart = new Cart({
      discountPolicy: discount,
      shippingCalculator: shipping,
      region: "US-CA",
    });
    cart.add(productA, 1);
    const result = await cart.checkout({
      priceFetcher: fetcher,
      inventoryChecker: checker,
      asyncTaxProvider: provider,
    });

    // Refreshed price: 2000
    expect(result.totals.subtotalCents).toBe(2000);
    // Discount: 200, discounted = 1800
    expect(result.totals.discountCents).toBe(200);
    // Tax: floor(5% of 1800) = 90
    expect(result.totals.taxCents).toBe(90);
    expect(result.totals.shippingCents).toBe(300);
    // total = 1800 + 90 + 300 = 2190
    expect(result.totals.totalCents).toBe(2190);
    expect(provider.getRate).toHaveBeenCalledWith("US-CA");
  });

  it("generates default InventoryError message when no reason given", async () => {
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        availableQuantity: 0,
      }),
    };
    const cart = new Cart();
    cart.add(productA, 2);
    await expect(cart.checkout({ inventoryChecker: checker })).rejects.toThrow(
      /insufficient stock/,
    );
  });

  it("checkout does not mutate internal cart state", async () => {
    const cart = new Cart();
    cart.add(productA, 2);
    await cart.checkout();
    expect(cart.itemCount).toBe(2);
    expect(cart.totals().subtotalCents).toBe(2000);
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("rate service down")),
    };
    const cart = new Cart();
    cart.add(productA, 1);
    await expect(
      cart.checkout({ asyncTaxProvider: provider }),
    ).rejects.toThrow("rate service down");
  });

  it("propagates priceFetcher rejection", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
    };
    const cart = new Cart();
    cart.add(productA, 1);
    await expect(cart.checkout({ priceFetcher: fetcher })).rejects.toThrow(
      "price service down",
    );
  });
});

